// The prod sharing gate (risk PV-A, GAPS G2): with PUBLIC_SHARING off, nothing can be made reachable without
// signing in, and everything else keeps working. Fixtures are generated bytes.

import { randomBytes } from "node:crypto";
import { FakeDigestStream, World, sha256hex, type User } from "./harness.js";

beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});
afterAll(() => {
  delete (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream;
});

describe("public sharing off", () => {
  let w: World;
  let owner: User;
  let A: { id: string; pub: string };
  let base: string;

  beforeEach(async () => {
    w = new World();
    A = w.newOrg();
    owner = w.newUser("owner");
    w.grant(A, owner, "owner");
    const lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Gate" })).json.data.library;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    w.env.PUBLIC_SHARING = "off";
  });

  const upload = async (extra: Record<string, unknown> = {}) => {
    const bytes = randomBytes(64);
    return w.call(owner, "POST", `${base}/uploads`, { name: `f${Math.random()}.bin`, size: bytes.length, sha256: sha256hex(bytes), mime: "application/octet-stream", ...extra });
  };

  it("refuses public uploads, public visibility, public batches, public library defaults and the random API", async () => {
    const pub = await upload({ visibility: "public" });
    expect(pub.status).toBe(409);
    expect(pub.json.error.code).toBe("public_sharing_off");

    const ok = await upload();
    expect(ok.status).toBe(201);
    const s = ok.json.data.session;
    const bytes = randomBytes(64);
    const s2 = (await w.call(owner, "POST", `${base}/uploads`, { name: "p.bin", size: 64, sha256: sha256hex(bytes), mime: "application/octet-stream" })).json.data.session;
    await w.put(owner, `${base}/uploads/${s2.id}/parts/1`, bytes);
    const file = (await w.call(owner, "POST", `${base}/uploads/${s2.id}/commit`)).json.data.file;
    expect(file.visibility).toBe("private");
    expect(s.id).toBeTruthy();

    expect((await w.call(owner, "PATCH", `${base}/files/${file.id}`, { visibility: "public" })).status).toBe(409);
    expect((await w.call(owner, "POST", `${base}/files:batch`, { action: "visibility", ids: [file.id], visibility: "public" })).status).toBe(409);
    expect((await w.call(owner, "PATCH", base, { visibilityDefault: "public" })).status).toBe(409);
    expect((await w.call(owner, "PATCH", base, { settings: { randomApiEnabled: true } })).status).toBe(409);
    expect((await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Pub", visibilityDefault: "public" })).status).toBe(409);

    // private work, renames and signed links still work
    expect((await w.call(owner, "PATCH", `${base}/files/${file.id}`, { name: "renamed.bin" })).status).toBe(200);
    expect((await w.call(owner, "PATCH", `${base}/files/${file.id}`, { visibility: "private" })).status).toBe(200);
    expect((await w.call(owner, "POST", `${base}/files/${file.id}/signed-url`, { expiresIn: 600 })).status).toBe(200);
    expect((await w.call(owner, "GET", base)).json.data.library.publicSharing).toBe(false);
  });

  it("files made public before the gate get no plain URL while it's off", async () => {
    w.env.PUBLIC_SHARING = "on";
    const bytes = randomBytes(64);
    const s = (await w.call(owner, "POST", `${base}/uploads`, { name: "old.bin", size: 64, sha256: sha256hex(bytes), mime: "application/octet-stream", visibility: "public" })).json.data.session;
    await w.put(owner, `${base}/uploads/${s.id}/parts/1`, bytes);
    const id = (await w.call(owner, "POST", `${base}/uploads/${s.id}/commit`)).json.data.file.id;
    await w.runPipelines();
    expect((await w.call(owner, "GET", `${base}/files/${id}`)).json.data.file.url).toMatch(/^https:/);
    w.env.PUBLIC_SHARING = "off";
    expect((await w.call(owner, "GET", `${base}/files/${id}`)).json.data.file.url).toBeNull();
  });

  it("a library made public before the gate uploads private while it's off", async () => {
    w.env.PUBLIC_SHARING = "on";
    await w.call(owner, "PATCH", base, { visibilityDefault: "public" });
    w.env.PUBLIC_SHARING = "off";
    const bytes = randomBytes(64);
    const s = (await w.call(owner, "POST", `${base}/uploads`, { name: "d.bin", size: 64, sha256: sha256hex(bytes), mime: "application/octet-stream" })).json.data.session;
    await w.put(owner, `${base}/uploads/${s.id}/parts/1`, bytes);
    const file = (await w.call(owner, "POST", `${base}/uploads/${s.id}/commit`)).json.data.file;
    expect(file.visibility).toBe("private");
  });
});
